require __DIR__ . '/_boot.php'; $id=admin_id($_GET['id'] ?? null); $statement=db()->prepare('SELECT o.*,u.name AS customer_name,u.email AS customer_email FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?'); $statement->execute([$id]); $order=$statement->fetch(); if (!$order) abort_request(404,'Order not found.');
$statement=db()->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id'); $statement->execute([$id]); $items=$statement->fetchAll(); $statement=db()->prepare('SELECT * FROM payments WHERE order_id=?'); $statement->execute([$id]); $payment=$statement->fetch();
$transitions=allowed_order_transitions($order['fulfillment_method'],$order['status']); $pageTitle=$order['order_reference']; $pageDescription='Placed '.$order['created_at']; require dirname(__DIR__, 2) . '/templates/admin_header.php';
?>
<a class="back-link" href="<?= e(url('/admin/orders.php')) ?>">← All orders</a><div class="order-layout"><div><section class="panel"><div class="panel-heading"><h2>Arrangement details</h2><span class="status status-<?= e($order['status']) ?>"><?= e(admin_label($order['status'])) ?></span></div><div class="table-wrap"><table><thead><tr><th>Arrangement</th><th>Quantity</th><th>Unit price</th><th>Line total</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= e($item['product_name']) ?></td><td><?= (int)$item['quantity'] ?></td><td><?= e(format_money($item['unit_price'])) ?></td><td><?= e(format_money(money_to_minor($item['unit_price'])*(int)$item['quantity'])) ?></td></tr><?php endforeach; ?></tbody></table></div><dl class="order-totals"><div><dt>Subtotal</dt><dd><?= e(format_money($order['subtotal'])) ?></dd></div><div><dt><?= $order['fulfillment_method']==='delivery' ? 'Delivery' : 'Pickup' ?> fee</dt><dd><?= e(format_money($order['fulfillment_fee'])) ?></dd></div><div class="total"><dt>Simulated total</dt><dd><?= e(format_money($order['total'])) ?></dd></div></dl></section>
<section class="panel detail-panel"><h2>Fulfillment</h2><dl class="detail-list"><div><dt>Method</dt><dd><?= e(admin_label($order['fulfillment_method'])) ?></dd></div><div><dt>Scheduled date</dt><dd><?= e($order['scheduled_date']) ?></dd></div><?php if ($order['fulfillment_method']==='delivery'): ?><div><dt>Recipient</dt><dd><?= e($order['recipient_name']) ?></dd></div><div><dt>Phone</dt><dd><?= e($order['recipient_phone']) ?></dd></div><div><dt>Delivery address</dt><dd><?= nl2br(e($order['delivery_address'])) ?></dd></div><?php endif; ?><div><dt>Gift message</dt><dd><?= $order['gift_message'] !== '' ? nl2br(e($order['gift_message'])) : 'No gift message' ?></dd></div></dl></section></div>
<div><section class="panel detail-panel"><h2>Manage order</h2><?php if (!$transitions): ?><p>This order is <?= e(admin_label($order['status'])) ?>. No further changes are available.</p><?php else: ?><p>Choose the next step for this <?= e($order['fulfillment_method']) ?> order.</p><form method="post" action="<?= e(url('/admin/actions/order-status.php')) ?>" class="status-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><label for="next-status">Next status</label><select id="next-status" name="status"><?php foreach ($transitions as $next): ?><option value="<?= e($next) ?>"><?= e(admin_label($next)) ?></option><?php endforeach; ?></select><button class="button" type="submit">Update status</button></form><?php if (in_array('cancelled',$transitions,true)): ?><p class="help-text">Cancelling returns stock once and marks the demo payment as simulated refunded.</p><?php endif; ?><?php endif; ?></section>
<section class="panel detail-panel"><h2>Customer</h2><p><?= e($order['customer_name']) ?><br><a href="mailto:<?= e($order['customer_email']) ?>"><?= e($order['customer_email']) ?></a></p></section><section class="panel detail-panel"><h2>Demo payment</h2><?php if ($payment): ?><span class="status"><?= e(admin_label($payment['status'])) ?></span><p class="reference"><?= e($payment['demo_reference']) ?></p><p><?= e(format_money($payment['amount'])) ?></p><?php else: ?><p>No demo payment recorded.</p><?php endif; ?><small>This is a simulation. No money was charged or refunded.</small></section></div></div>
